BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text UNIQUE NOT NULL, role text NOT NULL CHECK(role IN ('collector','actor')), status text NOT NULL DEFAULT 'HEALTHY', cooldown_until timestamptz, last_action_at timestamptz, meta_ig_user_id text, meta_page_id text, meta_access_token_encrypted text, meta_token_expires_at timestamptz, api_capabilities jsonb NOT NULL DEFAULT '{}');
CREATE TABLE account_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES accounts ON DELETE CASCADE, user_data_dir_path text NOT NULL, user_agent text, viewport jsonb, last_used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE account_health (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES accounts ON DELETE CASCADE, captured_at timestamptz NOT NULL DEFAULT now(), auth_errors int DEFAULT 0, navigation_errors int DEFAULT 0, action_rejections int DEFAULT 0, checkpoints_count int DEFAULT 0, latency_ms int, recent_success_rate numeric, api_error_rate numeric, api_rate_limited_count int DEFAULT 0, health_score numeric CHECK(health_score BETWEEN 0 AND 100));
CREATE TABLE campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE competitors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text UNIQUE NOT NULL, instagram_user_id text, followers_count int, follows_count int, media_count int, biography text, profile_picture_url text, last_synced_via_api_at timestamptz, last_crawled_at timestamptz, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','paused','archived')), added_by_user_id text, added_at timestamptz DEFAULT now(), notes text);
CREATE TABLE campaign_competitors (campaign_id uuid REFERENCES campaigns ON DELETE CASCADE, competitor_id uuid REFERENCES competitors ON DELETE CASCADE, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','paused','archived')), added_by_user_id text, added_at timestamptz DEFAULT now(), weight numeric NOT NULL DEFAULT 1, PRIMARY KEY(campaign_id,competitor_id));
CREATE TABLE campaign_scoring_config (campaign_id uuid PRIMARY KEY REFERENCES campaigns ON DELETE CASCADE, w_comments numeric DEFAULT 1, w_posts numeric DEFAULT 1, w_competitors numeric DEFAULT 1, w_recency numeric DEFAULT 1, w_intent numeric DEFAULT 1, w_semantic numeric DEFAULT 1, w_relationship numeric DEFAULT 1, lambda_freshness numeric DEFAULT .05, w_overlap_followed numeric DEFAULT 1, w_overlap_commented numeric DEFAULT 2, w_overlap_liked numeric DEFAULT 0, w_overlap_live numeric DEFAULT 2, w_overlap_search numeric DEFAULT 1, w_fb numeric DEFAULT 1, w_ret numeric DEFAULT 1, w_int numeric DEFAULT 1, w_dm numeric DEFAULT 1, w_conv numeric DEFAULT 1, w_cost numeric DEFAULT 1, source_weights jsonb DEFAULT '{}');
CREATE TABLE posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), competitor_id uuid NOT NULL REFERENCES competitors ON DELETE CASCADE, shortcode text NOT NULL, post_url text, posted_at timestamptz, comment_count_shown int, like_count_shown int, caption text, engagement_metrics jsonb DEFAULT '{}', source text CHECK(source IN ('api','scrape')), processed_at timestamptz, UNIQUE(competitor_id,shortcode));
CREATE TABLE comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES posts ON DELETE CASCADE, comment_external_id text NOT NULL, username text NOT NULL, parent_comment_id uuid REFERENCES comments, text text, commented_at timestamptz, collected_at timestamptz DEFAULT now(), source text DEFAULT 'scrape', profile_snippet jsonb DEFAULT '{}', UNIQUE(post_id,comment_external_id));
CREATE TABLE crawl_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES accounts, scope_type text, scope_id text, source text, started_at timestamptz DEFAULT now(), finished_at timestamptz, status text, items_seen int DEFAULT 0, items_new int DEFAULT 0, extraction_coverage numeric);
CREATE TABLE content_opportunities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid REFERENCES campaigns ON DELETE CASCADE, thesis text NOT NULL, angle text, hook text, evidence jsonb DEFAULT '{}', opportunity_score numeric DEFAULT 0, status text DEFAULT 'new', created_at timestamptz DEFAULT now());
CREATE TABLE own_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES accounts, ig_media_id text UNIQUE NOT NULL, media_type text, caption text, permalink text, posted_at timestamptz, insights jsonb DEFAULT '{}', last_synced_at timestamptz, content_opportunity_id uuid REFERENCES content_opportunities);
CREATE TABLE own_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES accounts, ig_comment_id text UNIQUE NOT NULL, media_id uuid REFERENCES own_media, from_username text, text text, commented_at timestamptz, is_reply boolean DEFAULT false, parent_ig_comment_id text, hidden boolean DEFAULT false, replied boolean DEFAULT false, classification_id uuid, fetched_at timestamptz DEFAULT now());
CREATE TABLE own_mentions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES accounts, ig_mention_id text UNIQUE NOT NULL, from_username text, media_id uuid REFERENCES own_media, comment_id uuid REFERENCES own_comments, text text, mentioned_at timestamptz, fetched_at timestamptz DEFAULT now());
CREATE TABLE own_dm_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES accounts, ig_thread_id text UNIQUE NOT NULL, participant_username text, participant_ig_user_id text, last_message_at timestamptz, unread_count int DEFAULT 0);
CREATE TABLE own_dm_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid REFERENCES own_dm_threads ON DELETE CASCADE, ig_message_id text UNIQUE NOT NULL, direction text CHECK(direction IN ('inbound','outbound')), text text, media_url text, sent_at timestamptz, delivered_at timestamptz, read_at timestamptz);
CREATE TABLE comment_classification (comment_id uuid NOT NULL, scope text NOT NULL CHECK(scope IN ('competitor','own')), intent text, topic text, sentiment text, purchase_signal boolean DEFAULT false, is_question boolean DEFAULT false, pain_point text, confidence numeric, embedding vector(384), classified_at timestamptz DEFAULT now(), PRIMARY KEY(comment_id,scope));
CREATE TABLE leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), instagram_user_id text, username_current text NOT NULL, profile_url text, first_seen_at timestamptz DEFAULT now(), last_seen_at timestamptz DEFAULT now());
CREATE UNIQUE INDEX leads_instagram_user_unique ON leads(instagram_user_id) WHERE instagram_user_id IS NOT NULL;
CREATE TABLE lead_username_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid REFERENCES leads ON DELETE CASCADE, username text, seen_at timestamptz DEFAULT now());
CREATE TABLE lead_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid REFERENCES leads ON DELETE CASCADE, campaign_id uuid REFERENCES campaigns, competitor_id uuid REFERENCES competitors, post_id uuid REFERENCES posts, comment_id uuid, source_kind text CHECK(source_kind IN ('comment','follower','search','collab','live','overlap')), discovered_at timestamptz DEFAULT now(), UNIQUE(lead_id,comment_id));
CREATE TABLE lead_profile (lead_id uuid PRIMARY KEY REFERENCES leads ON DELETE CASCADE, is_private boolean, followers_count int, following_count int, posts_count int, is_verified boolean, has_profile_pic boolean, fetched_at timestamptz);
CREATE TABLE lead_scores (lead_id uuid REFERENCES leads ON DELETE CASCADE, campaign_id uuid REFERENCES campaigns ON DELETE CASCADE, base_score numeric, intent_score numeric, relationship_score numeric, audience_overlap_score numeric, freshness_multiplier numeric, final_score numeric, priority text CHECK(priority IN ('P0','P1','P2','P3')), computed_at timestamptz DEFAULT now(), PRIMARY KEY(lead_id,campaign_id));
CREATE TABLE lead_score_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid REFERENCES leads, campaign_id uuid REFERENCES campaigns, base_score numeric, intent_score numeric, relationship_score numeric, final_score numeric, computed_at timestamptz DEFAULT now());
CREATE TABLE prospect_status (lead_id uuid REFERENCES leads ON DELETE CASCADE, campaign_id uuid REFERENCES campaigns ON DELETE CASCADE, status text NOT NULL DEFAULT 'new', stage text NOT NULL DEFAULT 'discovery', updated_at timestamptz DEFAULT now(), PRIMARY KEY(lead_id,campaign_id));
CREATE TABLE lead_status_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid REFERENCES leads, campaign_id uuid REFERENCES campaigns, from_status text, to_status text, at timestamptz DEFAULT now());
CREATE TABLE lead_interactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid REFERENCES leads, account_id uuid REFERENCES accounts, kind text NOT NULL, direction text CHECK(direction IN ('inbound','outbound','passive')), source text CHECK(source IN ('api','scrape','webhook','manual')), ref_type text, ref_id text, payload jsonb DEFAULT '{}', at timestamptz DEFAULT now());
CREATE TABLE engagement_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES accounts, lead_id uuid REFERENCES leads, campaign_id uuid REFERENCES campaigns, action_type text NOT NULL, target_ref_type text, target_ref_id text NOT NULL, status text DEFAULT 'awaiting_approval', priority text CHECK(priority IN ('P0','P1','P2','P3')), reason_code text NOT NULL DEFAULT 'UNKNOWN', execution_mode text CHECK(execution_mode IN ('api','scrape')), scheduled_for timestamptz, attempts int DEFAULT 0, last_error text, created_at timestamptz DEFAULT now(), executed_at timestamptz, completed_at timestamptz, suggested_by text, approved_by text, UNIQUE(account_id,lead_id,action_type,target_ref_id));
CREATE TABLE action_policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES accounts, action_type text, hourly_limit int DEFAULT 0, daily_limit int DEFAULT 0, cooldown_seconds int DEFAULT 0, enabled boolean DEFAULT false, execution_mode text, required_role text CHECK(required_role IN ('collector','actor')), params jsonb DEFAULT '{}', UNIQUE(account_id,action_type));
CREATE TABLE dm_drafts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid REFERENCES leads, thread_id uuid REFERENCES own_dm_threads, context jsonb DEFAULT '{}', variants jsonb NOT NULL, chosen_variant_id text, status text DEFAULT 'draft', trigger_kind text NOT NULL CHECK(trigger_kind IN ('inbound','reply_private_upgrade')), expires_at timestamptz, humanization_signature text, created_at timestamptz DEFAULT now(), sent_at timestamptz);
CREATE TABLE conversation_state (thread_id uuid PRIMARY KEY REFERENCES own_dm_threads, lead_id uuid REFERENCES leads, current_stage text, detected_intent text, detected_objections jsonb DEFAULT '{}', last_agent_action text, requires_human_review boolean DEFAULT true, updated_at timestamptz DEFAULT now());
CREATE TABLE message_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text, purpose text, base_prompt text, variables jsonb DEFAULT '{}', active boolean DEFAULT true, created_at timestamptz DEFAULT now());
CREATE TABLE generated_texts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), purpose text, ref_type text, ref_id text, text text, embedding vector(384), brand_voice_version text, created_at timestamptz DEFAULT now());
CREATE TABLE repetition_alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), generated_text_id uuid REFERENCES generated_texts, similar_text_id uuid REFERENCES generated_texts, cosine_similarity numeric, action_taken text, at timestamptz DEFAULT now());
CREATE TABLE topics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scope text, competitor_id uuid REFERENCES competitors, label text, embedding vector(384), momentum_7d numeric, momentum_30d numeric, first_seen_at timestamptz DEFAULT now(), last_seen_at timestamptz DEFAULT now());
CREATE TABLE pain_points (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), topic_id uuid REFERENCES topics ON DELETE CASCADE, label text, evidence jsonb DEFAULT '{}', weight numeric);
CREATE TABLE questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), topic_id uuid REFERENCES topics ON DELETE CASCADE, text text, frequency int, embedding vector(384));
CREATE TABLE opportunities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid REFERENCES campaigns, kind text, label text, evidence jsonb DEFAULT '{}', score numeric);
CREATE TABLE post_radar (post_id uuid PRIMARY KEY REFERENCES posts ON DELETE CASCADE, opportunity_score numeric, velocity numeric, new_leads int, avg_intent numeric, computed_at timestamptz DEFAULT now());
CREATE TABLE community_edges (from_lead_id uuid REFERENCES leads, to_context_type text, to_context_id uuid, weight numeric, last_reinforced_at timestamptz, PRIMARY KEY(from_lead_id,to_context_type,to_context_id));
CREATE TABLE communities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text, centroid_embedding vector(384), size int, cohesion_score numeric, detected_at timestamptz, last_refreshed_at timestamptz);
CREATE TABLE lead_community_membership (lead_id uuid REFERENCES leads, community_id uuid REFERENCES communities, membership_strength numeric, PRIMARY KEY(lead_id,community_id));
CREATE TABLE competitor_candidates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username_candidate text, discovery_reason text, overlap_score numeric, suggested_at timestamptz DEFAULT now(), status text DEFAULT 'new');
CREATE TABLE reciprocity_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid REFERENCES leads, account_id uuid REFERENCES accounts, trigger_action_id uuid REFERENCES engagement_actions, reciprocal_kind text, latency_seconds int, detected_at timestamptz DEFAULT now());
CREATE TABLE profile_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES accounts, captured_at timestamptz DEFAULT now(), followers_count int, follows_count int, posts_count int, engagement_rate numeric, reach_7d int, impressions_7d int);
CREATE TABLE conversion_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid REFERENCES leads, campaign_id uuid REFERENCES campaigns, kind text, value numeric, source text, ref jsonb DEFAULT '{}', at timestamptz DEFAULT now());
CREATE TABLE attributions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid REFERENCES leads, campaign_id uuid REFERENCES campaigns, competitor_id uuid REFERENCES competitors, post_id uuid REFERENCES posts, comment_id uuid, first_action_at timestamptz, last_action_at timestamptz, conversion_event_id uuid REFERENCES conversion_events, action_path jsonb DEFAULT '[]');
CREATE TABLE nba_recommendations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid REFERENCES leads, campaign_id uuid REFERENCES campaigns, suggested_action text, target_ref jsonb, rationale text, confidence numeric, suggested_at timestamptz DEFAULT now(), status text DEFAULT 'pending');
CREATE TABLE nba_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text, condition_expr text, action_expr text, priority int, active boolean DEFAULT true, hit_count int DEFAULT 0, last_hit_at timestamptz);
CREATE TABLE events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES accounts, campaign_id uuid REFERENCES campaigns, scope text, level text, payload jsonb DEFAULT '{}', created_at timestamptz DEFAULT now());
CREATE TABLE failed_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), queue_name text, job_id text, payload jsonb, error text, moved_at timestamptz DEFAULT now(), UNIQUE(queue_name,job_id));
CREATE TABLE alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text, severity text CHECK(severity IN ('info','warn','error','critical')), payload jsonb DEFAULT '{}', created_at timestamptz DEFAULT now(), acknowledged_at timestamptz, resolved_at timestamptz, decided_by text, fingerprint text);
CREATE TABLE review_inbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), item_type text, item_ref_id text, reason text, suggested_action jsonb, context jsonb, status text DEFAULT 'pending', decided_by text, decided_at timestamptz, decision_notes text, created_at timestamptz DEFAULT now());
CREATE TABLE follower_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), competitor_id uuid REFERENCES competitors, captured_at timestamptz DEFAULT now(), followers_hash text, followers_count_seen int, storage_ref text);
CREATE TABLE follower_deltas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), competitor_id uuid REFERENCES competitors, snapshot_from uuid REFERENCES follower_snapshots, snapshot_to uuid REFERENCES follower_snapshots, username text, ig_user_id text, delta_kind text CHECK(delta_kind IN ('new_follower','lost_follower')), detected_at timestamptz DEFAULT now());
CREATE TABLE search_terms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), term text, category text, region text, hashtag boolean DEFAULT false, active boolean DEFAULT true, frequency_hint_seconds int, last_run_at timestamptz, next_run_at timestamptz, hit_rate numeric, leads_generated int DEFAULT 0, avg_lead_quality numeric);
CREATE TABLE search_hits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), search_term_id uuid REFERENCES search_terms, run_id uuid REFERENCES crawl_runs, kind text, username text, permalink text, snippet text, discovered_at timestamptz DEFAULT now(), converted_to_lead boolean DEFAULT false);
CREATE TABLE candidate_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username_candidate text, discovered_via text CHECK(discovered_via IN ('collab','tag','mention','community_map','search','live')), relevance_score numeric, overlap_score numeric, evidence jsonb DEFAULT '{}', suggested_at timestamptz DEFAULT now(), status text DEFAULT 'new');
CREATE TABLE live_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), competitor_id uuid REFERENCES competitors, ig_broadcast_id text, started_at timestamptz, ended_at timestamptz, topic_inferred text, viewer_peak_seen int, source text);
CREATE TABLE live_interactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), live_event_id uuid REFERENCES live_events, lead_id uuid REFERENCES leads, kind text CHECK(kind IN ('comment','reaction','join','active_now')), payload jsonb DEFAULT '{}', at timestamptz DEFAULT now());
CREATE TABLE follow_retention (action_id uuid PRIMARY KEY REFERENCES engagement_actions, lead_id uuid REFERENCES leads, account_id uuid REFERENCES accounts, followed_at timestamptz, followed_back_at timestamptz, followback_latency_seconds int, retained_7d boolean, retained_30d boolean, retained_90d boolean, interactions_after_count int DEFAULT 0, unfollowed_by_target_at timestamptz, unfollowed_by_us_at timestamptz, last_checked_at timestamptz);
CREATE TABLE source_metrics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_type text, source_id text, campaign_id uuid REFERENCES campaigns, window_days int, leads_generated int, unique_leads int, followback_rate numeric, retention_7d_rate numeric, retention_30d_rate numeric, interaction_rate numeric, dm_initiated_rate numeric, dm_reply_rate numeric, conversion_rate numeric, source_score numeric, computed_at timestamptz DEFAULT now());
CREATE TABLE crawl_schedule (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_type text, source_id text, campaign_id uuid REFERENCES campaigns, current_interval_seconds int, min_interval_seconds int, max_interval_seconds int, last_run_at timestamptz, next_run_at timestamptz, consecutive_empty_runs int DEFAULT 0, quality_score numeric, last_updated_at timestamptz DEFAULT now(), locked_by_user boolean DEFAULT false, locked_until timestamptz, UNIQUE(source_type,source_id,campaign_id));
CREATE TABLE crawl_schedule_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_type text, source_id text, old_interval_seconds int, new_interval_seconds int, reason text, at timestamptz DEFAULT now());
CREATE TABLE scheduled_publications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), content_opportunity_id uuid REFERENCES content_opportunities, media_asset_ref text, caption text, scheduled_for timestamptz, status text DEFAULT 'scheduled', ig_media_id text, error text);
CREATE TABLE error_triggers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text, match_expr text, severity text, channels jsonb, dedup_key_template text, escalation_policy jsonb, throttle_seconds int, active boolean DEFAULT true, hit_count int DEFAULT 0, last_hit_at timestamptz);
CREATE TABLE notification_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), alert_id uuid REFERENCES alerts, channel text, status text, provider_id text, attempts int DEFAULT 0, last_error text, sent_at timestamptz);
CREATE TABLE worker_heartbeats (worker text, instance_id text, last_beat_at timestamptz, jobs_done_window int, jobs_failed_window int, backlog_seen int, p95_latency_ms numeric, state text, PRIMARY KEY(worker,instance_id));
CREATE TABLE slo_breaches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), queue_name text, metric text, observed numeric, threshold numeric, severity text, opened_at timestamptz DEFAULT now(), resolved_at timestamptz);
CREATE TABLE audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id text, action text, target text, before jsonb, after jsonb, at timestamptz DEFAULT now());
CREATE FUNCTION audit_log_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'audit_log is append-only'; END $$;
CREATE TRIGGER audit_log_no_update BEFORE UPDATE OR DELETE ON audit_log FOR EACH ROW EXECUTE FUNCTION audit_log_immutable();

CREATE INDEX posts_competitor_posted_idx ON posts(competitor_id,posted_at DESC);
CREATE INDEX campaign_competitors_active_idx ON campaign_competitors(campaign_id,status) WHERE status='active';
CREATE INDEX comments_post_collected_idx ON comments(post_id,collected_at);
CREATE INDEX lead_sources_lead_idx ON lead_sources(lead_id);
CREATE INDEX engagement_account_status_idx ON engagement_actions(account_id,status,priority);
CREATE INDEX lead_scores_campaign_idx ON lead_scores(campaign_id,priority,final_score DESC);
CREATE INDEX lead_interactions_timeline_idx ON lead_interactions(lead_id,at DESC);
CREATE INDEX review_inbox_status_idx ON review_inbox(status,created_at);
CREATE INDEX follower_delta_idx ON follower_deltas(competitor_id,delta_kind,detected_at DESC);
CREATE INDEX search_terms_due_idx ON search_terms(active,next_run_at);
CREATE INDEX candidate_sources_score_idx ON candidate_sources(status,overlap_score DESC);
CREATE INDEX live_interactions_event_idx ON live_interactions(live_event_id,at DESC);
CREATE INDEX comment_embedding_hnsw ON comment_classification USING hnsw(embedding vector_cosine_ops);
CREATE INDEX generated_embedding_hnsw ON generated_texts USING hnsw(embedding vector_cosine_ops);
CREATE INDEX communities_embedding_hnsw ON communities USING hnsw(centroid_embedding vector_cosine_ops);

CREATE MATERIALIZED VIEW mv_topic_trends AS SELECT id,label,momentum_7d,momentum_30d FROM topics WITH NO DATA;
CREATE MATERIALIZED VIEW mv_audience_overlap AS SELECT campaign_id,lead_id,audience_overlap_score,final_score FROM lead_scores ORDER BY audience_overlap_score DESC NULLS LAST WITH NO DATA;
CREATE MATERIALIZED VIEW mv_engagement_effectiveness AS SELECT campaign_id,action_type,count(*) actions,count(*) FILTER(WHERE status='done') successes FROM engagement_actions GROUP BY campaign_id,action_type WITH NO DATA;

INSERT INTO campaigns(name,status) VALUES('Rota de Ataque','active'),('Gazeta Concursos','active');
INSERT INTO accounts(username,role,status,api_capabilities) VALUES('@handle_collector','collector','AUTH_REQUIRED','{}'),('@handle_actor','actor','AUTH_REQUIRED','{}');
INSERT INTO campaign_scoring_config(campaign_id) SELECT id FROM campaigns WHERE name IN ('Rota de Ataque','Gazeta Concursos');
INSERT INTO action_policies(account_id,action_type,enabled,execution_mode,required_role,daily_limit) SELECT id,'scrape',true,'scrape','collector',200 FROM accounts WHERE role='collector';
INSERT INTO action_policies(account_id,action_type,enabled,execution_mode,required_role,daily_limit) SELECT id,action_type,false,'both','actor',20 FROM accounts CROSS JOIN (VALUES('follow'),('like_post'),('reply_public'),('reply_private'),('dm'),('publish')) actions(action_type) WHERE role='actor';
COMMIT;
